
/* My Besti — scroll companion. Trails the scroll with a soft lag, hops sides.
 * Self-contained: atlas + renderer inlined. Exposes window.mybestiScroll. */
(function () {
  'use strict';
  if (document.getElementById('mybesti-scroll')) return;
/* mybesti pet core — shared sprite renderer.
 * One 8x11 "Work Pet" atlas, 192x208 cells. State-driven canvas animation.
 * Used by: web widget (mybesti-widget.js) + browser userscript (mybesti.user.js).
 * ponytail: states/frames hardcoded to the Prism-and-Purl atlas layout;
 *           add a manifest.json loader when a 2nd atlas ships.
 */
(function (root) {
  var CELL_W = 192, CELL_H = 208, COLS = 8;
  // row -> {state, frames}
  var STATES = {
    idle:            { row: 0, frames: 6 },
    'running-right': { row: 1, frames: 8 },
    'running-left':  { row: 2, frames: 8 },
    waving:          { row: 3, frames: 4 },
    jumping:         { row: 4, frames: 5 },
    failed:          { row: 5, frames: 8 },
    waiting:         { row: 6, frames: 6 },
    running:         { row: 7, frames: 6 },
    review:          { row: 8, frames: 6 },
    look1:           { row: 9, frames: 8 },
    look2:           { row: 10, frames: 8 }
  };

  function createPet(opts) {
    opts = opts || {};
    var src   = opts.src;                       // spritesheet URL or dataURL (required)
    var scale = opts.scale || 0.5;              // 1 = 192x208 native output
    var sourceScale = opts.sourceScale || 1;   // 0.5 when atlas is half-size
    var fps   = opts.fps   || 8;
    var state = opts.state || 'idle';
    var loop  = opts.loop !== false;

    var cv = document.createElement('canvas');
    cv.width  = Math.round(CELL_W * scale);
    cv.height = Math.round(CELL_H * scale);
    cv.style.imageRendering = 'auto';
    cv.style.display = 'block';
    var ctx = cv.getContext('2d');

    var img = new Image();
    img.crossOrigin = 'anonymous';
    var ready = false, frame = 0, timer = null, curr = STATES[state] || STATES.idle;

    function draw() {
      var cw = CELL_W * sourceScale, ch = CELL_H * sourceScale;
      var sx = (frame % COLS) * cw;
      var sy = curr.row * ch;
      ctx.clearRect(0, 0, cv.width, cv.height);
      if (ready) ctx.drawImage(img, sx, sy, cw, ch, 0, 0, cv.width, cv.height);
    }
    function tick() {
      frame++;
      if (frame >= curr.frames) { if (loop) frame = 0; else { frame = curr.frames - 1; stop(); } }
      draw();
    }
    function start() { stop(); timer = setInterval(tick, 1000 / fps); }
    function stop()  { if (timer) { clearInterval(timer); timer = null; } }

    img.onload = function () { ready = true; draw(); start(); };
    img.onerror = function () { console.warn('[mybesti] spritesheet failed to load:', src); };
    img.src = src;

    return {
      el: cv,
      setState: function (s) { if (STATES[s]) { curr = STATES[s]; frame = 0; if (!timer) start(); draw(); } },
      setScale: function (f) { scale = f; cv.width = Math.round(CELL_W * f); cv.height = Math.round(CELL_H * f); draw(); },
      play: start, pause: stop,
      states: Object.keys(STATES)
    };
  }

  root.MyBesti = { createPet: createPet, STATES: STATES, CELL_W: CELL_W, CELL_H: CELL_H };
})(typeof window !== 'undefined' ? window : this);


  var host = document.createElement('div');
  host.id = 'mybesti-scroll';
  host.setAttribute('aria-hidden', 'true');
  Object.assign(host.style, {
    position: 'fixed', zIndex: '2147483646', left: '18px', top: '12px',
    width: '96px', height: '104px', pointerEvents: 'none',
    filter: 'drop-shadow(0 3px 5px rgba(0,0,0,.42))'
  });
  var style = document.createElement('style');
  style.textContent = '@keyframes mybestiHop{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}'
    + '#mybesti-scroll{animation:mybestiHop 1.7s ease-in-out infinite}'
    + '@media(prefers-reduced-motion:reduce){#mybesti-scroll{animation:none}}';
  document.documentElement.appendChild(style);
  (document.body || document.documentElement).appendChild(host);

  // Slow run cycle (low fps) so the jog feels calm, not frantic.
  var pet = MyBesti.createPet({
    src: 'data:image/png;base64,', scale: .5, sourceScale: .5, fps: 6, state: 'running'
  });
  host.appendChild(pet.el);
  window.mybestiScroll = pet;

  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // state: current (rendered) and target positions; we ease toward target.
  var st = { top: 12, left: 18, tTop: 12, tLeft: 18, cur: 'idle' };

  function recompute() {
    var doc = document.documentElement;
    var max = (doc.scrollHeight - window.innerHeight) || 1;
    var p = Math.min(1, Math.max(0, window.scrollY / max));
    st.tTop = 12 + p * (window.innerHeight - 132);
    var side = p < 0.5 ? 0 : 1;
    st.tLeft = side === 0 ? 18 : Math.max(18, window.innerWidth - 116);
  }

  function setPet(s) { if (s !== st.cur) { st.cur = s; pet.setState(s); } }

  var EASE = reduce ? 0.25 : 0.06; // low = more lag/trail
  function frame() {
    recompute();
    st.top += (st.tTop - st.top) * EASE;
    st.left += (st.tLeft - st.left) * EASE;
    host.style.top = st.top.toFixed(1) + 'px';
    host.style.left = st.left.toFixed(1) + 'px';
    // running while still trailing the target; idle once settled.
    var dx = st.tTop - st.top, dy = st.tLeft - st.left;
    var dist = Math.sqrt(dx * dx + dy * dy);
    setPet(dist > 1.2 ? 'running' : 'idle');
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
